<script setup>
import { ref } from 'vue';
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import AppLayout from '../../../Layouts/AppLayout.vue';
import Dialog from '../../../Components/Shared/Dialog.vue';
defineOptions({ layout: AppLayout });
defineProps({ store: Object, periods: Object, weeklyUrl: String, createUrl: String, sessionBlocked: Boolean, overviewUrl: String });
const page = usePage(); const action = ref(null); const busy = ref(false);
const labels = { draft: 'Draft', scheduled: 'Scheduled', open: 'Open', ended: 'Ended', closed: 'Stopped', cancelled: 'Cancelled' };
const date = value => new Intl.DateTimeFormat('en-GB', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Asia/Jakarta' }).format(new Date(value));
const confirm = () => { busy.value = true; router.patch(action.value.url, {}, { onSuccess: () => { action.value = null; }, onFinish: () => { busy.value = false; } }); };
</script>
<template>
    <Head title="Open orders" /><Link :href="overviewUrl" class="text-sm text-stone-500 hover:underline">← My store</Link>
    <div class="mt-5 flex flex-wrap justify-between gap-4"><div><p class="text-xs text-stone-500">{{ store.name }}</p><h1 class="mt-2 text-3xl font-semibold">Open orders</h1><p class="mt-3 text-sm text-stone-500">Set your sales schedule, menu and quotas.</p></div><div class="flex items-start gap-3"><Link :href="weeklyUrl" class="rounded-xl border border-stone-300 px-4 py-3 text-sm">Weekly schedule</Link><Link v-if="!sessionBlocked" :href="createUrl" class="rounded-xl bg-[#504941] px-4 py-3 text-sm font-medium text-white">New session</Link></div></div>
    <p v-if="page.props.status" role="status" class="mt-6 rounded-xl bg-green-50 p-4 text-sm text-green-800">{{ page.props.status }}</p><div v-if="Object.keys(page.props.errors).length" role="alert" class="mt-5 text-sm text-red-700"><p v-for="(message, key) in page.props.errors" :key="key">{{ message }}</p></div>
    <div class="mt-7 overflow-x-auto rounded-2xl border border-stone-200 bg-[#fffdf9]"><p v-if="sessionBlocked" class="border-b border-stone-200 bg-stone-50 p-4 text-sm text-stone-500">Finish the current session and outstanding orders before opening another.</p><table class="w-full min-w-[720px] text-left text-sm"><thead class="border-b border-stone-200 bg-stone-50 text-xs text-stone-500"><tr><th class="px-5 py-4">Session</th><th class="px-5 py-4">Schedule · WIB</th><th class="px-5 py-4">Status</th><th class="px-5 py-4">Actions</th></tr></thead><tbody class="divide-y divide-stone-100"><tr v-for="period in periods.data" :key="period.id"><td class="px-5 py-5"><p class="font-medium">{{ period.name }}</p><p class="mt-2 text-xs text-stone-500">{{ period.itemCount }} products · {{ [period.pickup ? 'Pickup' : '', period.delivery ? 'Delivery' : ''].filter(Boolean).join(' / ') || 'No method yet' }}</p></td><td class="px-5 py-5"><p>{{ date(period.opensAt) }}</p><p class="mt-2 text-xs text-stone-500">Until {{ date(period.closesAt) }}</p></td><td class="px-5 py-5"><span class="rounded-full px-3 py-1.5 text-xs" :class="period.status === 'open' ? 'bg-green-50 text-green-800' : 'bg-stone-100 text-stone-600'">{{ labels[period.status] }}</span></td><td class="px-5 py-5"><div class="flex flex-wrap gap-2"><Link :href="period.ordersUrl" class="rounded-lg border border-stone-300 px-3 py-2">Orders ({{ period.orderCount }})</Link><Link v-if="period.editUrl" :href="period.editUrl" class="rounded-lg border border-stone-300 px-3 py-2">Edit draft</Link><button v-if="period.closeUrl" class="rounded-lg border border-stone-300 px-3 py-2" @click="action = { url: period.closeUrl, label: 'Stop orders', name: period.name }">Stop orders</button><button v-if="period.cancelUrl" class="rounded-lg border border-red-200 px-3 py-2 text-red-700" @click="action = { url: period.cancelUrl, label: 'Cancel session', name: period.name }">Cancel</button></div></td></tr><tr v-if="!periods.data.length"><td colspan="4" class="px-5 py-12 text-center text-stone-500">No sessions yet. Create your first open order.</td></tr></tbody></table></div>
    <nav v-if="periods.prev_page_url || periods.next_page_url" class="mt-5 flex justify-between text-sm"><Link v-if="periods.prev_page_url" :href="periods.prev_page_url" class="underline">← Previous</Link><span v-else /><Link v-if="periods.next_page_url" :href="periods.next_page_url" class="underline">Next →</Link></nav>
    <Dialog :open="Boolean(action)" :title="action?.label" :busy="busy" @close="action = null"><p class="text-sm leading-7">{{ action?.label }} “{{ action?.name }}”?</p><p v-if="action?.label === 'Stop orders'" class="mt-3 text-sm leading-6 text-stone-500">Customers will no longer be able to place new orders. Existing orders and payments stay unchanged and can still be processed.</p><p v-else class="mt-3 text-sm leading-6 text-stone-500">A session can only be cancelled before it has any customer orders.</p><div v-if="Object.keys(page.props.errors).length" role="alert" class="mt-4 text-sm text-red-700"><p v-for="(message,key) in page.props.errors" :key="key">{{ message }}</p></div><div class="mt-6 flex justify-end gap-3"><button :disabled="busy" class="rounded-xl border border-stone-300 px-4 py-3 text-sm" @click="action = null">Back</button><button :disabled="busy" class="rounded-xl bg-[#504941] px-4 py-3 text-sm text-white" @click="confirm">{{ busy ? 'Saving…' : 'Confirm' }}</button></div></Dialog>
</template>
